// Dead Wars: The Last Boat - art contract (data generated by tools/lbart.py from art/lb.txt
// into build/gen/lbart.c). Hand-written header: names and sizes here are the contract.
#ifndef LBART_H
#define LBART_H
#include <stdint.h>

// People: 16x16 OBJ, 2 frames (idle/step), facing RIGHT, survivor palette (pal_survivor),
// 4bpp tiles in 1D order (TL, TR, BL, BR), same layout as unit_gfx.
enum { LBG_MARA, LBG_DOC, LBG_JUNE, LBG_HOLT, LBG_ROSA, LBG_TESS, LBG_MAN, LBG_WOMAN, LBG_COUNT };
extern const uint8_t lbart_person_gfx[LBG_COUNT][2][128];

// Roofs: 16x16 BG metatiles drawn over building tiles, terrain palette (pal_terrain indices,
// team colours 13-15 for the roof so ownership can tint it). 9-slice + one sign per kind.
// Building footprints are 2..4 wide and 2 high: top row uses NW [N...] NE, bottom row SW [S...] SE.
enum { LBR_NW, LBR_N, LBR_NE, LBR_W, LBR_C, LBR_E, LBR_SW, LBR_S, LBR_SE,
       LBR_SIGN_HOUSE, LBR_SIGN_SHOP, LBR_SIGN_GARAGE, LBR_SIGN_PHARMACY, LBR_COUNT };
#define LBART_BG_TILE_BASE 224          // first BG tile in charblock 0 (terrain ends at 218)
#define LBART_BG_TILE_COUNT_MAX 288     // tiles 224..511
extern const int lbart_bg_tile_count;
extern const uint8_t  lbart_bg_tiles[];          // lbart_bg_tile_count * 32 bytes
extern const uint16_t lbart_roof_meta[LBR_COUNT][4]; // TL,TR,BL,BR: tile index (0-based in lbart_bg_tiles) | hflip<<10 | vflip<<11

// Icons: 16x16 OBJ, cursor palette (pal_cursor indices). Doors are drawn on the outside edge
// of the door tile; the S/E variants are flipped for N/W.
enum { LBI_DOOR_S, LBI_DOOR_E, LBI_BARRICADE_S, LBI_BARRICADE_E, LBI_CACHE, LBI_EXIT,
       LBI_HIDDEN, LBI_INFECTED, LBI_DOWNED, LBI_NOISE, LBI_COUNT };
extern const uint8_t lbart_icon_gfx[LBI_COUNT][128];

#define OBJT_LBPERSON 768                    // LBG_COUNT x 2 frames x 4 tiles
#define OBJT_LBICON   (OBJT_LBPERSON + 64)   // LBI_COUNT x 4 tiles

// Journey map backdrop: full screen 240x160 (30x20 tiles), its own BG palette, shown on
// charblock 1 like the title (tiles <= 512).
extern const int lbart_journey_tile_count;
extern const uint8_t  lbart_journey_tiles[];     // lbart_journey_tile_count * 32 bytes
extern const uint16_t lbart_journey_map[20][30]; // tile index | flips (palette bits 0)
extern const uint16_t lbart_journey_pal[16];

#endif
